/**
 * Ambient declaration of the TV render bench's virtual module (plan R0-02), generated by
 * `apps/tizen/scripts/bench-atlas.mjs` `shmupRenderBench()` in the bench builds only
 * (`vite.bench.config.ts`) — the game's build never resolves it.
 *
 * @module
 */
declare module 'virtual:shmup-render-bench' {
  import type { AtlasManifest } from '@shmup/render-pixi';
  /** One density's atlas: the real atlas ×s (nearest-neighbour), its pages next to the page. */
  export interface BenchAtlasModule {
    /** The density factor `s` (1, 1.5, 2.25). */
    readonly density: number;
    /** `x1`, `x1.5`, `x2.25`. */
    readonly label: string;
    /** The scaled manifest (inlined — no `fetch()` on the TV, decision D25). */
    readonly manifest: AtlasManifest;
    /** Page URLs relative to the page (`assets/atlas/bench-x1.5-0.png`, …). */
    readonly pageUrls: readonly string[];
  }
  /** One shipped particle-preset file (`content/fx/*.fx.json`). */
  export interface BenchFxFile {
    /** Path relative to `content/`. */
    readonly path: string;
    /** The parsed JSON document. */
    readonly data: unknown;
  }
  /** The atlases, in density order. */
  export const atlases: readonly BenchAtlasModule[];
  /** The particle presets. */
  export const fx: readonly BenchFxFile[];
  /** Both. */
  const bench: {
    readonly atlases: readonly BenchAtlasModule[];
    readonly fx: readonly BenchFxFile[];
  };
  export default bench;
}
